CREATE TYPE "AsyncFailureCategory" AS ENUM ('INFRASTRUCTURE_TRANSIENT', 'PROVIDER_TRANSIENT', 'PROVIDER_RATE_LIMITED', 'PROVIDER_PERMANENT', 'INVALID_PAYLOAD', 'UNSUPPORTED_VERSION', 'BUSINESS_REJECTION', 'PROCESSOR_TIMEOUT', 'UNKNOWN');
CREATE TYPE "AsyncFailureLifecycle" AS ENUM ('RETRY_EXHAUSTED', 'ACKNOWLEDGED', 'DISMISSED');
CREATE TYPE "AsyncReplayStatus" AS ENUM ('REQUESTED', 'PUBLISHED', 'SUCCEEDED', 'FAILED');
CREATE TABLE "AsyncFailure" ("id" UUID NOT NULL, "outboxEventId" UUID NOT NULL, "processorIdentity" VARCHAR(128) NOT NULL, "queueName" VARCHAR(100) NOT NULL, "jobName" VARCHAR(100) NOT NULL, "jobId" VARCHAR(128), "eventType" VARCHAR(100) NOT NULL, "eventVersion" INTEGER NOT NULL, "correlationId" VARCHAR(128) NOT NULL, "aggregateReference" VARCHAR(128), "attemptCount" INTEGER NOT NULL DEFAULT 0, "lastAttemptAt" TIMESTAMPTZ(3), "category" "AsyncFailureCategory" NOT NULL, "reasonCode" VARCHAR(64) NOT NULL, "lifecycleState" "AsyncFailureLifecycle" NOT NULL DEFAULT 'RETRY_EXHAUSTED', "quarantinedAt" TIMESTAMPTZ(3), "acknowledgedAt" TIMESTAMPTZ(3), "dismissedAt" TIMESTAMPTZ(3), "applicationVersion" VARCHAR(64), "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(3) NOT NULL, CONSTRAINT "AsyncFailure_pkey" PRIMARY KEY ("id"), CONSTRAINT "AsyncFailure_reasonCode_check" CHECK ("reasonCode" ~ '^[a-z][a-z0-9_.-]{0,63}$'), CONSTRAINT "AsyncFailure_attemptCount_check" CHECK ("attemptCount" >= 0), CONSTRAINT "AsyncFailure_eventVersion_check" CHECK ("eventVersion" > 0));
CREATE UNIQUE INDEX "AsyncFailure_outboxEventId_processorIdentity_key" ON "AsyncFailure"("outboxEventId", "processorIdentity");
CREATE INDEX "AsyncFailure_createdAt_id_idx" ON "AsyncFailure"("createdAt", "id");
CREATE INDEX "AsyncFailure_lifecycleState_quarantinedAt_createdAt_id_idx" ON "AsyncFailure"("lifecycleState", "quarantinedAt", "createdAt", "id");
CREATE INDEX "AsyncFailure_eventType_eventVersion_createdAt_id_idx" ON "AsyncFailure"("eventType", "eventVersion", "createdAt", "id");
ALTER TABLE "AsyncFailure" ADD CONSTRAINT "AsyncFailure_outboxEventId_fkey" FOREIGN KEY ("outboxEventId") REFERENCES "OutboxEvent"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "AsyncReplay" ("id" UUID NOT NULL, "failureId" UUID NOT NULL, "deterministicJobId" VARCHAR(128) NOT NULL, "status" "AsyncReplayStatus" NOT NULL DEFAULT 'REQUESTED', "requestedBy" UUID, "requestedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "claimedAt" TIMESTAMPTZ(3), "leaseExpiresAt" TIMESTAMPTZ(3), "attemptCount" INTEGER NOT NULL DEFAULT 0, "lastAttemptAt" TIMESTAMPTZ(3), "completedAt" TIMESTAMPTZ(3), "failureReasonCode" VARCHAR(64), "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AsyncReplay_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AsyncReplay_deterministicJobId_key" ON "AsyncReplay"("deterministicJobId");
CREATE INDEX "AsyncReplay_failureId_createdAt_id_idx" ON "AsyncReplay"("failureId", "createdAt", "id");
CREATE INDEX "AsyncReplay_status_leaseExpiresAt_createdAt_id_idx" ON "AsyncReplay"("status", "leaseExpiresAt", "createdAt", "id");
ALTER TABLE "AsyncReplay" ADD CONSTRAINT "AsyncReplay_failureId_fkey" FOREIGN KEY ("failureId") REFERENCES "AsyncFailure"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
